import numpy as np
import time
from solver import Solver

solver = Solver()

# Test multiple cases
test_cases = [
    {
        "t0": 0.0,
        "t1": 400.0,
        "y0": [0.89, 0.01, 0.005, 0.095],
        "params": {"beta": 0.35, "sigma": 0.2, "gamma": 0.1, "omega": 0.002}
    },
    {
        "t0": 0.0,
        "t1": 100.0,
        "y0": [0.9, 0.05, 0.03, 0.02],
        "params": {"beta": 0.5, "sigma": 0.3, "gamma": 0.15, "omega": 0.01}
    },
    {
        "t0": 0.0,
        "t1": 200.0,
        "y0": [0.8, 0.1, 0.05, 0.05],
        "params": {"beta": 0.4, "sigma": 0.25, "gamma": 0.12, "omega": 0.005}
    }
]

for i, problem in enumerate(test_cases):
    start = time.time()
    result = solver.solve(problem)
    elapsed = time.time() - start
    print(f"Case {i+1}: t1={problem['t1']}, sum={sum(result):.10f}, time={elapsed:.4f}s")
    print(f"  Result: {[f'{x:.8f}' for x in result]}")
